export function getTranslation(locale: Locale): TranslationKeys {
  const t = translations[locale];
  if (t && Object.keys(t).length > 0 && typeof (t as any).appName === 'string') return t as TranslationKeys;
  return translations.en;
}

export function t(key: keyof TranslationKeys, locale: Locale): string {
  const dict = (translations[locale] as TranslationKeys) || translations.en;
  const val = (dict as any)[key];
  return typeof val === 'string' ? val : (translations.en as any)[key] || String(key);
}